      }
      n++;
      bInNum = false;
    }
    szText++;
  }
  if ( bInNum && (n < nSize) ) {
    num[b] = 0;
    if (!strncmp(num, "nan", 3) || !strncmp(num, "-nan", 4)) {
      pBuf[n] = (T)nanf(num);
