        cause_value = OGS_GTP2_CAUSE_CONTEXT_NOT_FOUND;
    } else {
        sgwc_ue = sgwc_ue_find_by_id(sess->sgwc_ue_id);
        ogs_assert(sgwc_ue);
    }

