    for (AstGram& g : grams) {
        append(g.defs, g.inherited_defs);
        append(g.entry, g.inherited_entry);
        append(g.pre_rule, g.inherited_pre_rule);
        append(g.post_rule, g.inherited_post_rule);
    }

