before:
auto fsutil::sanitize_path( const fs::path& path ) -> fs::path {
    if ( path == L"/" ) {
        return L"_";
    }

    if ( is_drive_relative( path ) ) {
        // Drive-relative paths are sanitized as C_<rest of the path> (e.g., C:file.txt -> C_file.txt).
        const auto sanitizedRoot = sanitize_path_component( path.root_path().native() );
        return sanitizedRoot + sanitize_path_components( path.relative_path() ).native();
    }

    // Absolute paths: C:/abc/COM0/?invalid:filename.txt -> C_/abc/_COM0/_invalid_filename.txt
    // Relative paths:   /abc/COM0/?invalid:filename.txt -> abc/_COM0/_invalid_filename.txt
    //                    abc/COM0/?invalid:filename.txt -> abc/_COM0/_invalid_filename.txt
    return sanitize_path_components( path );
}

after:
BIT7Z_NODISCARD
auto sanitize_path_join( const fs::path& base, const fs::path& path ) -> fs::path {
#if defined( _WIN32 ) && defined( BIT7Z_PATH_SANITIZATION )
    return base / fsutil::sanitize_path( path );
#else
    if ( is_absolute( path ) ) {
#ifdef BIT7Z_PATH_SANITIZATION
        return base / path.relative_path();
#else
        throw BitException(
            "Invalid item path",
            make_error_code( BitError::ItemHasAbsolutePath ),
            path_to_tstring( path )
        );
#endif
    }

#ifdef _WIN32
    if ( path.has_root_path() ) {
        // The path either has a root name (e.g., drive letter) or a root directory
        // (not both, since it's a relative path).
        return base / path.relative_path();
    }
#endif

    return base / path;
#endif
}

before:
auto InternalCategory::default_error_condition( int errorValue ) const noexcept -> std::error_condition {
    switch ( static_cast< BitError >( errorValue ) ) {
        case BitError::FilterNotSpecified:
        case BitError::FormatFeatureNotSupported:
        case BitError::IndicesNotSpecified:
        case BitError::InvalidArchivePath:
        case BitError::InvalidOutputBufferSize:
        case BitError::InvalidCompressionMethod:
        case BitError::InvalidDictionarySize:
        case BitError::InvalidIndex:
        case BitError::InvalidWordSize:
        case BitError::ItemIsAFolder:
        case BitError::NonEmptyOutputBuffer:
        case BitError::NullOutputBuffer:
        case BitError::InvalidZipPassword:
            return std::make_error_condition( std::errc::invalid_argument );
        case BitError::NoMatchingItems:
            return std::make_error_condition( std::errc::no_such_file_or_directory );
        case BitError::RequestedWrongVariantType:
        case BitError::UnsupportedOperation:
        case BitError::UnsupportedVariantType:
            return std::make_error_condition( std::errc::not_supported );
        case BitError::ItemMarkedAsDeleted:
        case BitError::WrongUpdateMode:
            return std::make_error_condition( std::errc::operation_not_permitted );
        default:
            return error_category::default_error_condition( errorValue );
    }
}

static int
parse_matrix_header(char *line,
	int *width, int *height, double *scale, double *offset)
{
	double header[4];
	char *p, *q;
	int i;

	/* Stop at newline.
	 */
	if ((p = strchr(line, '\r')) ||
		((p = strchr(line, '\n'))))
		*p = '\0';

	for (i = 0, p = line; (q = vips_break_token(p, " \t")) && i < 4; i++, p = q)
		if (vips_strtod(p, &header[i])) {
			vips_error("matload", _("bad number \"%s\""), p);
			return -1;
		}

	if (i < 4)
		header[3] = 0.0;
	if (i < 3)
		header[2] = 1.0;
	if (i < 2) {
		vips_error("matload", "%s", _("no width / height"));
		return -1;
	}

	if (floor(header[0]) != header[0] ||
		floor(header[1]) != header[1]) {
		vips_error("mask2vips", "%s", _("width / height not int"));
		return -1;
	}

	/* Width / height can be 65536 for a 16-bit LUT, for example.
	 */
	*width = header[0];
	*height = header[1];
	if (*width <= 0 ||
		*width > 100000 ||
		*height <= 0 ||
		*height > 100000) {
		vips_error("mask2vips", "%s", _("width / height out of range"));
		return -1;
	}
	if (header[2] == 0.0) {
		vips_error("mask2vips", "%s", _("zero scale"));
		return -1;
	}

	*scale = header[2];
	*offset = header[3];

	return 0;
}

