static gboolean
vips_foreign_load_matrix_file_is_a(const char *filename)
{
	unsigned char line[80];
	guint64 bytes;
	int width;
	int height;
	double scale;
	double offset;
	int result;

	if ((bytes = vips__get_bytes(filename, line, 79)) <= 0)
		return FALSE;
	line[bytes] = '\0';

	vips_error_freeze();
	result = parse_matrix_header((char *) line,
		&width, &height, &scale, &offset);
	vips_error_thaw();

	return result == 0;
}

