			const unsigned idx0 = (c & 0x00FC0000) >> 18;
			const unsigned idx1 = (c & 0x0003F000) >> 12;

			WINPR_ASSERT(idx0 < alphabetCount);
			WINPR_ASSERT(idx1 < alphabetCount);

			*p++ = alphabet[idx0];
			*p++ = alphabet[idx1];
