before:
static Bool filelist_next_url(GF_Filter *filter, GF_FileListCtx *ctx, char szURL[GF_MAX_PATH], Bool is_splice_update)
{
	u32 len;
	u32 url_crc = 0;
	Bool last_found = GF_FALSE;
	FILE *f;
	u32 nb_repeat=0, lineno=0;
	u64 start_range=0, end_range=0;
	Double start=0, stop=0;
	GF_Fraction64 splice_start, splice_end;
	char chap_name[1024];
	Bool do_cat=0;
	Bool do_del=0;
	Bool is_end=0;
	Bool keep_splice=0;
	Bool mark_only=0;
	Bool no_sync=0;
	u32 start_flags=0;
	u32 end_flags=0;

	if (ctx->file_list) {
		FileListEntry *fentry, *next;

		if (ctx->revert) {
			if (!ctx->file_list_idx) {
				if (!ctx->floop) return GF_FALSE;
				if (ctx->floop>0) ctx->floop--;
				ctx->file_list_idx = gf_list_count(ctx->file_list);
			}
			ctx->file_list_idx --;
		} else {
			ctx->file_list_idx ++;
			if (ctx->file_list_idx >= (s32) gf_list_count(ctx->file_list)) {
				if (!ctx->floop) return GF_FALSE;
				if (ctx->floop>0) ctx->floop--;
				ctx->file_list_idx = 0;
			}
		}
		fentry = gf_list_get(ctx->file_list, ctx->file_list_idx);
		strncpy(szURL, fentry->file_name, sizeof(char)*(GF_MAX_PATH-1) );
		szURL[GF_MAX_PATH-1] = 0;
		filelist_check_implicit_cat(ctx, szURL);
		next = gf_list_get(ctx->file_list, ctx->file_list_idx + 1);
		if (next)
			ctx->current_file_dur_us = next->last_mod_time - fentry->last_mod_time;
		return GF_TRUE;
	}

	if (ctx->wait_update_start || is_splice_update) {
		u64 last_modif_time = gf_file_modification_time(ctx->file_path);
		if (ctx->last_file_modif_time >= last_modif_time) {
			if (!is_splice_update) {
				u64 diff = gf_sys_clock() - ctx->wait_update_start;
				if (diff > ctx->timeout) {
					GF_LOG(GF_LOG_WARNING, GF_LOG_MEDIA, ("[FileList] Timeout refreshing playlist after %d ms, triggering eos\n", diff));
					ctx->ka = 0;
				}
			}
			return GF_FALSE;
		}
		ctx->wait_update_start = 0;
		ctx->last_file_modif_time = last_modif_time;
	}

	splice_start.num = splice_end.num = 0;
	splice_start.den = splice_end.den = 0;
	chap_name[0]=0;

	f = gf_fopen(ctx->file_path, "rt");
	if (!f) return GF_FALSE;

	while (f) {
		char *l = gf_fgets(szURL, GF_MAX_PATH, f);
		if (!l || (gf_feof(f) && !szURL[0]) ) {
			if (ctx->floop != 0) {
				gf_fseek(f, 0, SEEK_SET);
				//load first line
				if (last_found) {
					if (!ctx->floop) return GF_FALSE;
					if (ctx->floop>0) ctx->floop--;
					ctx->last_url_crc=0;
				}
				last_found = GF_TRUE;
				lineno=0;
				continue;
			}
			if (ctx->ka && !is_end && !last_found && url_crc) {
				gf_fseek(f, 0, SEEK_SET);
				last_found = GF_TRUE;
				lineno=0;
				continue;
			}

			gf_fclose(f);
			if (is_end) {
				ctx->ka = 0;
			} else if (ctx->ka) {
				ctx->wait_update_start = gf_sys_clock();
				ctx->last_file_modif_time = gf_file_modification_time(ctx->file_path);
			}
			return GF_FALSE;
		}
		url_crc = 0;

		len = (u32) strlen(szURL);
		//in keep-alive mode, each line shall end with \n, of not consider the file is not yet ready
		if (ctx->ka && !is_end && len && (szURL[len-1]!='\n')) {
			gf_fclose(f);
			ctx->wait_update_start = gf_sys_clock();
			ctx->last_file_modif_time = gf_file_modification_time(ctx->file_path);
			return GF_FALSE;
		}
		//strip all \r, \n, \t at the end
		while (len && strchr("\n\r\t ", szURL[len-1])) {
			szURL[len-1] = 0;
			len--;
		}
		if (!len) continue;

		//comment
		if (szURL[0] == '#') {
			//ignored line
			if (szURL[1] == '#')
				continue;

			char *args = szURL+1;
			nb_repeat=0;
			start=stop=0;
			do_cat = 0;
			start_range=end_range=0;
			if (ctx->pid_props) {
				gf_free(ctx->pid_props);
				ctx->pid_props = NULL;
			}

			while (args) {
				char c;
				Bool skip_first=GF_FALSE;
				char *sep, *aval = NULL;
				while (args[0]==' ') args++;

				sep = strchr(args, ' ');
				if (strncmp(args, "props", 5))
					aval = strchr(args, ',');

				if (!strncmp(args, "chap=\"", 6)) {
					sep = strchr(args+7, '\"');
					if (sep) skip_first = GF_TRUE;
				}

				if (sep && aval && (aval < sep))
					sep = aval;
				else if (aval)
					sep = aval;

				if (sep) {
					c = sep[0];
					sep[0] = 0;
				}
				aval = strchr(args, '=');
				if (aval) {
					aval[0] = 0;
					aval++;
					if (skip_first) aval++;
				}

				if (!strcmp(args, "repeat")) {
					if (aval)
						nb_repeat = atoi(aval);
				} else if (!strcmp(args, "start")) {
					if (aval)
						start = atof(aval);
				} else if (!strcmp(args, "stop")) {
					if (aval)
						stop = atof(aval);
				} else if (!strcmp(args, "cat")) {
					do_cat = GF_TRUE;
				} else if (!strcmp(args, "del")) {
					do_del = GF_TRUE;
				} else if (do_cat && !strcmp(args, "srange")) {
					if (aval)
						sscanf(aval, LLU, &start_range);
				} else if (do_cat && !strcmp(args, "send")) {
					if (aval)
						sscanf(aval, LLU, &end_range);
				} else if (!strcmp(args, "end")) {
					if (ctx->ka) {
						is_end = GF_TRUE;
						ctx->ka=0;
					}
				} else if (!strcmp(args, "ka")) {
					if (aval)
						sscanf(aval, "%u", &ctx->ka);
				} else if (!strcmp(args, "raw")) {
					u32 raw_type = 0;
					if (aval) {
						if (!stricmp(aval, "av")) raw_type = FL_RAW_AV;
						else if (!stricmp(aval, "a")) raw_type = FL_RAW_AUDIO;
						else if (!stricmp(aval, "v")) raw_type = FL_RAW_VIDEO;
					}
					if (filter && (ctx->raw != raw_type) ) {
						ctx->raw = raw_type;
						filelist_override_caps(filter, ctx);
					}
				} else if (!strcmp(args, "floop")) {
					ctx->floop = aval ? atoi(aval) : 0;
				} else if (!strcmp(args, "props")) {
					if (ctx->pid_props) gf_free(ctx->pid_props);
					ctx->pid_props = aval ? gf_strdup(aval) : NULL;
				} else if (!strcmp(args, "out")) {
					filelist_parse_splice_time(aval, &splice_start, &start_flags);
				} else if (!strcmp(args, "in")) {
					filelist_parse_splice_time(aval, &splice_end, &end_flags);
				} else if (!strcmp(args, "keep")) {
					keep_splice = GF_TRUE;
				} else if (!strcmp(args, "mark")) {
					mark_only = GF_TRUE;
				} else if (!strcmp(args, "nosync")) {
					no_sync = GF_TRUE;
				} else if (!strcmp(args, "sprops")) {
					if (ctx->splice_props) gf_free(ctx->splice_props);
					ctx->splice_props = aval ? gf_strdup(aval) : NULL;
				} else if (!strcmp(args, "chap") && aval) {
					if (aval) {
						strncpy(chap_name, aval, 1023);
						chap_name[1023]=0;
					}
				} else if (!strcmp(args, "base_url")) {
					if (ctx->temp_base_url) gf_free(ctx->temp_base_url);
					ctx->temp_base_url = aval && aval[0] ? gf_strdup(aval) : NULL;
				} else {
					if (!ctx->unknown_params || !strstr(ctx->unknown_params, args)) {
						GF_LOG(GF_LOG_WARNING, GF_LOG_MEDIA, ("[FileList] Unrecognized directive %s, ignoring\n", args));
						gf_dynstrcat(&ctx->unknown_params, args, ",");
					}
				}

				if (aval) aval[0] = '=';

				if (!sep) break;
				sep[0] = c;
				args = sep+1;
			}
			continue;
		}
		//increase line num only for non-comment lines
		lineno++;

		url_crc = gf_crc_32(szURL, (u32) strlen(szURL) );
		if (!ctx->last_url_crc) {
			ctx->last_url_crc = url_crc;
			ctx->last_url_lineno = lineno;
			break;
		}
		if ( ((ctx->last_url_crc == url_crc) && (ctx->last_url_lineno == lineno))
			|| (is_splice_update && (ctx->last_splice_crc==url_crc))
		) {
			last_found = GF_TRUE;
			nb_repeat=0;
			start=stop=0;
			do_cat=0;
			start_range=end_range=0;
			if (is_splice_update)
				break;
			splice_start.den = splice_end.den = 0;
			keep_splice = 0;
			mark_only = 0;
			start_flags=0;
			end_flags=0;
			no_sync=0;
			continue;
		}
		if (last_found) {
			ctx->last_url_crc = url_crc;
			ctx->last_url_lineno = lineno;
			break;
		}
		nb_repeat=0;
		start=stop=0;
		do_cat=0;
		do_del=0;
		start_range=end_range=0;
		splice_start.den = splice_end.den = 0;
		keep_splice = 0;
		mark_only = 0;
		start_flags=0;
		end_flags=0;
		no_sync=0;
	}
	gf_fclose(f);

	if (is_splice_update && !last_found)
		return GF_FALSE;

	//not in active splicing and we had a splice start set, trigger a new splice
	if ((ctx->splice_state != FL_SPLICE_ACTIVE) && splice_start.den) {
		//activate if:
		if (
			//new new splice start is undefined (prepare for new splice)
			(splice_start.num<0)
			// or new splice start is defined and prev splice start was undefined
			|| ((splice_start.num>=0) && ((ctx->splice_start.num < 0) || !ctx->splice_start.den) )
			// or new splice time is greater than previous one
			|| (ctx->splice_start.num * splice_start.den < splice_start.num * ctx->splice_start.den)
		) {

			ctx->init_splice_start = ctx->splice_start = splice_start;
			if (!splice_end.den) {
				ctx->splice_end.num = -1;
				ctx->splice_end.den = 1;
			} else {
				ctx->splice_end = splice_end;
			}
			ctx->init_splice_end = ctx->splice_end;

			ctx->splice_state = FL_SPLICE_BEFORE;
			//items to be spliced are the ones after the spliced content
			ctx->last_splice_crc = ctx->last_url_crc = url_crc;
			ctx->last_url_lineno = lineno;
			ctx->last_splice_lineno = lineno;
			ctx->last_file_modif_time = gf_file_modification_time(ctx->file_path);
			ctx->keep_splice = keep_splice;
			ctx->mark_only = mark_only;
			ctx->init_flags_splice_start = ctx->flags_splice_start = start_flags;
			ctx->init_flags_splice_end = ctx->flags_splice_end = end_flags;

			if (!ctx->first_loaded) {
				if (ctx->splice_start.num == -2)
					ctx->splice_start.num = -1;
				if (ctx->splice_end.num == -2)
					ctx->splice_end.num = -1;
			}
		}
	}
	//in active splicing and we hava a splice end set, update splice value if previous one was undefined or not set
	else if ((ctx->splice_state == FL_SPLICE_ACTIVE)  && splice_end.den && (!ctx->splice_end.den || (ctx->splice_end.num<0))) {
		ctx->init_splice_end = ctx->splice_end = splice_end;
		ctx->init_flags_splice_end = ctx->flags_splice_end = end_flags;
	}

	if (is_splice_update)
		return GF_FALSE;

	if ((ctx->splice_state == FL_SPLICE_ACTIVE) && (splice_start.den || splice_end.den)) {
		GF_LOG(GF_LOG_ERROR, GF_LOG_MEDIA, ("[FileList] URL %s is a main splice content but expecting a regular content in active splice\n", szURL));
		return GF_FALSE;
	}


	len = (u32) strlen(szURL);
	while (len && strchr("\r\n", szURL[len-1])) {
		szURL[len-1] = 0;
		len--;
	}
	ctx->nb_repeat = nb_repeat;
	ctx->start = start;
	ctx->stop = stop;
	ctx->do_cat = do_cat;
	ctx->skip_sync = no_sync;

	if (ctx->temp_base_url) {
		char *res_url = gf_url_concatenate(ctx->temp_base_url, szURL);
		if (res_url) {
			strncpy(szURL, res_url, GF_MAX_PATH-2);
			szURL[GF_MAX_PATH]=0;
			gf_free(res_url);
		}
	}

	if (!ctx->floop)
		ctx->do_del = (do_del || ctx->fdel) ? GF_TRUE : GF_FALSE;
	ctx->start_range = start_range;
	ctx->end_range = end_range;
	filelist_check_implicit_cat(ctx, szURL);
	if (chap_name[0])
		push_chapter(ctx, chap_name);
	return GF_TRUE;
}

after:
static Bool filelist_next_url(GF_Filter *filter, GF_FileListCtx *ctx, char szURL[GF_MAX_PATH], Bool is_splice_update)
{
	u32 len;
	u32 url_crc = 0;
	Bool last_found = GF_FALSE;
	FILE *f;
	u32 nb_repeat=0, lineno=0;
	u64 start_range=0, end_range=0;
	Double start=0, stop=0;
	GF_Fraction64 splice_start, splice_end;
	char chap_name[1024];
	Bool do_cat=0;
	Bool do_del=0;
	Bool is_end=0;
	Bool keep_splice=0;
	Bool mark_only=0;
	Bool no_sync=0;
	u32 start_flags=0;
	u32 end_flags=0;

	if (ctx->file_list) {
		FileListEntry *fentry, *next;

		if (ctx->revert) {
			if (!ctx->file_list_idx) {
				if (!ctx->floop) return GF_FALSE;
				if (ctx->floop>0) ctx->floop--;
				ctx->file_list_idx = gf_list_count(ctx->file_list);
			}
			ctx->file_list_idx --;
		} else {
			ctx->file_list_idx ++;
			if (ctx->file_list_idx >= (s32) gf_list_count(ctx->file_list)) {
				if (!ctx->floop) return GF_FALSE;
				if (ctx->floop>0) ctx->floop--;
				ctx->file_list_idx = 0;
			}
		}
		fentry = gf_list_get(ctx->file_list, ctx->file_list_idx);
		strncpy(szURL, fentry->file_name, sizeof(char)*(GF_MAX_PATH-1) );
		szURL[GF_MAX_PATH-1] = 0;
		filelist_check_implicit_cat(ctx, szURL);
		next = gf_list_get(ctx->file_list, ctx->file_list_idx + 1);
		if (next)
			ctx->current_file_dur_us = next->last_mod_time - fentry->last_mod_time;
		return GF_TRUE;
	}

	if (ctx->wait_update_start || is_splice_update) {
		u64 last_modif_time = gf_file_modification_time(ctx->file_path);
		if (ctx->last_file_modif_time >= last_modif_time) {
			if (!is_splice_update) {
				u64 diff = gf_sys_clock() - ctx->wait_update_start;
				if (diff > ctx->timeout) {
					GF_LOG(GF_LOG_WARNING, GF_LOG_MEDIA, ("[FileList] Timeout refreshing playlist after %d ms, triggering eos\n", diff));
					ctx->ka = 0;
				}
			}
			return GF_FALSE;
		}
		ctx->wait_update_start = 0;
		ctx->last_file_modif_time = last_modif_time;
	}

	splice_start.num = splice_end.num = 0;
	splice_start.den = splice_end.den = 0;
	chap_name[0]=0;

	f = gf_fopen(ctx->file_path, "rt");
	if (!f) return GF_FALSE;

	while (f) {
		char *l = gf_fgets(szURL, GF_MAX_PATH, f);
		if (!l || (gf_feof(f) && !szURL[0]) ) {
			if (ctx->floop != 0) {
				gf_fseek(f, 0, SEEK_SET);
				//load first line
				if (last_found) {
					if (!ctx->floop) return GF_FALSE;
					if (ctx->floop>0) ctx->floop--;
					ctx->last_url_crc=0;
				}
				last_found = GF_TRUE;
				lineno=0;
				continue;
			}
			if (ctx->ka && !is_end && !last_found && url_crc) {
				gf_fseek(f, 0, SEEK_SET);
				last_found = GF_TRUE;
				lineno=0;
				continue;
			}

			gf_fclose(f);
			if (is_end) {
				ctx->ka = 0;
			} else if (ctx->ka) {
				ctx->wait_update_start = gf_sys_clock();
				ctx->last_file_modif_time = gf_file_modification_time(ctx->file_path);
			}
			return GF_FALSE;
		}
		url_crc = 0;

		len = (u32) strlen(szURL);
		//in keep-alive mode, each line shall end with \n, of not consider the file is not yet ready
		if (ctx->ka && !is_end && len && (szURL[len-1]!='\n')) {
			gf_fclose(f);
			ctx->wait_update_start = gf_sys_clock();
			ctx->last_file_modif_time = gf_file_modification_time(ctx->file_path);
			return GF_FALSE;
		}
		//strip all \r, \n, \t at the end
		while (len && strchr("\n\r\t ", szURL[len-1])) {
			szURL[len-1] = 0;
			len--;
		}
		if (!len) continue;

		//comment
		if (szURL[0] == '#') {
			//ignored line
			if (szURL[1] == '#')
				continue;

			char *args = szURL+1;
			nb_repeat=0;
			start=stop=0;
			do_cat = 0;
			start_range=end_range=0;
			if (ctx->pid_props) {
				gf_free(ctx->pid_props);
				ctx->pid_props = NULL;
			}

			while (args) {
				char c;
				Bool skip_first=GF_FALSE;
				char *sep, *aval = NULL;
				while (args[0]==' ') args++;

				sep = strchr(args, ' ');
				if (strncmp(args, "props", 5))
					aval = strchr(args, ',');

				if (!strncmp(args, "chap=\"", 6)) {
					sep = strchr(args+7, '\"');
					if (sep) skip_first = GF_TRUE;
				}

				if (sep && aval && (aval < sep))
					sep = aval;
				else if (aval)
					sep = aval;

				if (sep) {
					c = sep[0];
					sep[0] = 0;
				}
				aval = strchr(args, '=');
				if (aval) {
					aval[0] = 0;
					aval++;
					if (skip_first) aval++;
				}

				if (!strcmp(args, "repeat")) {
					if (aval)
						nb_repeat = atoi(aval);
				} else if (!strcmp(args, "start")) {
					if (aval)
						start = atof(aval);
				} else if (!strcmp(args, "stop")) {
					if (aval)
						stop = atof(aval);
				} else if (!strcmp(args, "cat")) {
					do_cat = GF_TRUE;
				} else if (!strcmp(args, "del")) {
					do_del = GF_TRUE;
				} else if (do_cat && !strcmp(args, "srange")) {
					if (aval)
						sscanf(aval, LLU, &start_range);
				} else if (do_cat && !strcmp(args, "send")) {
					if (aval)
						sscanf(aval, LLU, &end_range);
				} else if (!strcmp(args, "end")) {
					if (ctx->ka) {
						is_end = GF_TRUE;
						ctx->ka=0;
					}
				} else if (!strcmp(args, "ka")) {
					if (aval)
						sscanf(aval, "%u", &ctx->ka);
				} else if (!strcmp(args, "raw")) {
					u32 raw_type = 0;
					if (aval) {
						if (!stricmp(aval, "av")) raw_type = FL_RAW_AV;
						else if (!stricmp(aval, "a")) raw_type = FL_RAW_AUDIO;
						else if (!stricmp(aval, "v")) raw_type = FL_RAW_VIDEO;
					}
					if (filter && (ctx->raw != raw_type) ) {
						ctx->raw = raw_type;
						filelist_override_caps(filter, ctx);
					}
				} else if (!strcmp(args, "floop")) {
					ctx->floop = aval ? atoi(aval) : 0;
				} else if (!strcmp(args, "props")) {
					if (ctx->pid_props) gf_free(ctx->pid_props);
					ctx->pid_props = aval ? gf_strdup(aval) : NULL;
				} else if (!strcmp(args, "out")) {
					filelist_parse_splice_time(aval, &splice_start, &start_flags);
				} else if (!strcmp(args, "in")) {
					filelist_parse_splice_time(aval, &splice_end, &end_flags);
				} else if (!strcmp(args, "keep")) {
					keep_splice = GF_TRUE;
				} else if (!strcmp(args, "mark")) {
					mark_only = GF_TRUE;
				} else if (!strcmp(args, "nosync")) {
					no_sync = GF_TRUE;
				} else if (!strcmp(args, "sprops")) {
					if (ctx->splice_props) gf_free(ctx->splice_props);
					ctx->splice_props = aval ? gf_strdup(aval) : NULL;
				} else if (!strcmp(args, "chap") && aval) {
					if (aval) {
						strncpy(chap_name, aval, 1023);
						chap_name[1023]=0;
					}
				} else if (!strcmp(args, "base_url")) {
					if (ctx->temp_base_url) gf_free(ctx->temp_base_url);
					ctx->temp_base_url = aval && aval[0] ? gf_strdup(aval) : NULL;
				} else {
					if (!ctx->unknown_params || !strstr(ctx->unknown_params, args)) {
						GF_LOG(GF_LOG_WARNING, GF_LOG_MEDIA, ("[FileList] Unrecognized directive %s, ignoring\n", args));
						gf_dynstrcat(&ctx->unknown_params, args, ",");
					}
				}

				if (aval) aval[0] = '=';

				if (!sep) break;
				sep[0] = c;
				args = sep+1;
			}
			continue;
		}
		//increase line num only for non-comment lines
		lineno++;

		url_crc = gf_crc_32(szURL, (u32) strlen(szURL) );
		if (!ctx->last_url_crc) {
			ctx->last_url_crc = url_crc;
			ctx->last_url_lineno = lineno;
			break;
		}
		if ( ((ctx->last_url_crc == url_crc) && (ctx->last_url_lineno == lineno))
			|| (is_splice_update && (ctx->last_splice_crc==url_crc))
		) {
			last_found = GF_TRUE;
			nb_repeat=0;
			start=stop=0;
			do_cat=0;
			start_range=end_range=0;
			if (is_splice_update)
				break;
			splice_start.den = splice_end.den = 0;
			keep_splice = 0;
			mark_only = 0;
			start_flags=0;
			end_flags=0;
			no_sync=0;
			continue;
		}
		if (last_found) {
			ctx->last_url_crc = url_crc;
			ctx->last_url_lineno = lineno;
			break;
		}
		nb_repeat=0;
		start=stop=0;
		do_cat=0;
		do_del=0;
		start_range=end_range=0;
		splice_start.den = splice_end.den = 0;
		keep_splice = 0;
		mark_only = 0;
		start_flags=0;
		end_flags=0;
		no_sync=0;
	}
	gf_fclose(f);

	if (is_splice_update && !last_found)
		return GF_FALSE;

	//not in active splicing and we had a splice start set, trigger a new splice
	if ((ctx->splice_state != FL_SPLICE_ACTIVE) && splice_start.den) {
		//activate if:
		if (
			//new new splice start is undefined (prepare for new splice)
			(splice_start.num<0)
			// or new splice start is defined and prev splice start was undefined
			|| ((splice_start.num>=0) && ((ctx->splice_start.num < 0) || !ctx->splice_start.den) )
			// or new splice time is greater than previous one
			|| (ctx->splice_start.num * splice_start.den < splice_start.num * ctx->splice_start.den)
		) {

			ctx->init_splice_start = ctx->splice_start = splice_start;
			if (!splice_end.den) {
				ctx->splice_end.num = -1;
				ctx->splice_end.den = 1;
			} else {
				ctx->splice_end = splice_end;
			}
			ctx->init_splice_end = ctx->splice_end;

			ctx->splice_state = FL_SPLICE_BEFORE;
			//items to be spliced are the ones after the spliced content
			ctx->last_splice_crc = ctx->last_url_crc = url_crc;
			ctx->last_url_lineno = lineno;
			ctx->last_splice_lineno = lineno;
			ctx->last_file_modif_time = gf_file_modification_time(ctx->file_path);
			ctx->keep_splice = keep_splice;
			ctx->mark_only = mark_only;
			ctx->init_flags_splice_start = ctx->flags_splice_start = start_flags;
			ctx->init_flags_splice_end = ctx->flags_splice_end = end_flags;

			if (!ctx->first_loaded) {
				if (ctx->splice_start.num == -2)
					ctx->splice_start.num = -1;
				if (ctx->splice_end.num == -2)
					ctx->splice_end.num = -1;
			}
		}
	}
	//in active splicing and we hava a splice end set, update splice value if previous one was undefined or not set
	else if ((ctx->splice_state == FL_SPLICE_ACTIVE)  && splice_end.den && (!ctx->splice_end.den || (ctx->splice_end.num<0))) {
		ctx->init_splice_end = ctx->splice_end = splice_end;
		ctx->init_flags_splice_end = ctx->flags_splice_end = end_flags;
	}

	if (is_splice_update)
		return GF_FALSE;

	if ((ctx->splice_state == FL_SPLICE_ACTIVE) && (splice_start.den || splice_end.den)) {
		GF_LOG(GF_LOG_ERROR, GF_LOG_MEDIA, ("[FileList] URL %s is a main splice content but expecting a regular content in active splice\n", szURL));
		return GF_FALSE;
	}


	len = (u32) strlen(szURL);
	while (len && strchr("\r\n", szURL[len-1])) {
		szURL[len-1] = 0;
		len--;
	}
	ctx->nb_repeat = nb_repeat;
	ctx->start = start;
	ctx->stop = stop;
	ctx->do_cat = do_cat;
	ctx->skip_sync = no_sync;

	if (ctx->temp_base_url) {
		char *res_url = gf_url_concatenate(ctx->temp_base_url, szURL);
		if (res_url) {
			strncpy(szURL, res_url, GF_MAX_PATH-2);
			szURL[GF_MAX_PATH-1]=0;
			gf_free(res_url);
		}
	}

	if (!ctx->floop)
		ctx->do_del = (do_del || ctx->fdel) ? GF_TRUE : GF_FALSE;
	ctx->start_range = start_range;
	ctx->end_range = end_range;
	filelist_check_implicit_cat(ctx, szURL);
	if (chap_name[0])
		push_chapter(ctx, chap_name);
	return GF_TRUE;
}

