		CF (entry->format, EXIF_FORMAT_SHORT, v, maxlen)
		CC (entry->components, 2, v, maxlen)
		vs = exif_get_short (entry->data, entry->order);
		switch (vs) {
		case 1:
			strncpy (v, _("Automatic"), maxlen);
			break;
		case 2:
			{
				ExifShort v2 = exif_get_short (entry->data + 2, entry->order);
