				if (*pathp) {
					ret = -EINVAL;
					goto err;
				}
				node = root;
			} else {
				/* Only the root node may have an empty name */
				if (!*pathp || is_reserved_name(pathp)) {
					ret = -EINVAL;
					goto err;
				}
				node = of_new_node(node, pathp);
			}

			break;

		case FDT_END_NODE:
			if (!node) {
				pr_err("unflatten: too many end nodes\n");
				ret = -EINVAL;
				goto err;
			}

			node = node->parent;

			dt_struct = dt_struct_advance(&f, dt_struct, FDT_TAGSIZE, 0);
			if (!dt_struct) {
				ret = -ESPIPE;
				goto err;
			}

			break;

		case FDT_PROP:
			fdt_prop = infdt + dt_struct;
			if (!dt_ptr_ok(fdt, fdt_prop)) {
				ret = -ESPIPE;
				goto err;
			}

